    th { text-align: left; padding: 0.5rem 0.75rem; color: #8b949e; font-weight: 500;
         border-bottom: 1px solid #30363d; }
    tbody tr { border-bottom: 1px solid #21262d; }
    tbody tr:hover { background: #161b22; }
    td { padding: 0.5rem 0.75rem; vertical-align: top; }

    .badge {
      display: inline-block; padding: 0.15rem 0.5rem; border-radius: 3px;
      font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: .04em;
    }
    .badge-critical { background: rgba(255,77,79,.2);  color: #ff4d4f; }
    .badge-high     { background: rgba(250,140,22,.2); color: #fa8c16; }
    .badge-medium   { background: rgba(250,173,20,.2); color: #faad14; }
    .badge-low      { background: rgba(82,196,26,.2);  color: #52c41a; }
    .badge-info     { background: rgba(24,144,255,.2); color: #1890ff; }

    .new-badge {
      display: inline-block; padding: .1rem .4rem; border-radius: 3px; font-size: .65rem;
      font-weight: 700; background: #3fb950; color: #000; margin-left: .4rem;
      animation: fadeout 4s forwards;
    }
    @keyframes fadeout { 0%,70%{opacity:1} 100%{opacity:0} }

    .target { font-family: monospace; font-size: 0.8rem; color: #58a6ff; }
    .tool   { font-size: 0.75rem; color: #6e7681; }
    .ts     { font-size: 0.75rem; color: #6e7681; white-space: nowrap; }
    .desc   { color: #c9d1d9; }
    .cve    { font-size: 0.75rem; color: #e3b341; }

    details { margin-top: 0.4rem; }
    summary { font-size: 0.75rem; color: #6e7681; cursor: pointer; user-select: none; list-style: none; }
    summary::before { content: "▶ evidence"; }
    details[open] summary::before { content: "▼ evidence"; }
    pre.evidence {
      margin-top: 0.4rem; padding: 0.6rem; background: #010409;
      border: 1px solid #21262d; border-radius: 4px;
      font-family: "SFMono-Regular", Consolas, monospace; font-size: 0.75rem;
      color: #7ee787; white-space: pre-wrap; word-break: break-all;
      max-height: 260px; overflow-y: auto;
    }

    .copy-gh-btn {
      display: inline-flex; align-items: center; gap: 0.3rem;
      background: none; border: 1px solid #30363d; border-radius: 4px;
      color: #6e7681; padding: 0.15rem 0.45rem; font-size: 0.72rem;
      cursor: pointer; transition: color .15s, border-color .15s; vertical-align: middle;
      margin-left: 0.5rem; white-space: nowrap;
    }
    .copy-gh-btn:hover { color: #58a6ff; border-color: #58a6ff; }
    .copy-gh-btn.copied { color: #3fb950; border-color: #3fb950; }

    .replay-btn {
      display: inline-flex; align-items: center; gap: 0.3rem;
      background: none; border: 1px solid #30363d; border-radius: 4px;
      color: #d29922; padding: 0.15rem 0.45rem; font-size: 0.72rem;
      cursor: pointer; transition: color .15s, border-color .15s; vertical-align: middle;
      margin-left: 0.3rem; white-space: nowrap;
    }
    .replay-btn:hover { color: #e3b341; border-color: #e3b341; }
    .replay-btn.copied { color: #3fb950; border-color: #3fb950; }

    .fix-btn {
      display: inline-flex; align-items: center; gap: 0.3rem;
      background: none; border: 1px solid #30363d; border-radius: 4px;
      color: #a371f7; padding: 0.15rem 0.45rem; font-size: 0.72rem;
      cursor: pointer; transition: color .15s, border-color .15s; vertical-align: middle;
      margin-left: 0.3rem; white-space: nowrap;
    }
    .fix-btn:hover { color: #c49bff; border-color: #c49bff; }

    .remediation-detail {
      background: #161b22; border: 1px solid #30363d; border-radius: 6px;
      padding: 1rem; margin-top: 0.5rem; font-size: 0.82rem;
    }
    .remediation-detail pre { background: #0d1117; padding: 0.75rem; border-radius: 4px; overflow-x: auto; }
    .remediation-detail .effort-badge {
      display: inline-block; padding: 0.1rem 0.4rem; border-radius: 3px; font-size: 0.7rem; font-weight: 600;
    }
    .effort-low { background: #238636; color: #fff; }
    .effort-medium { background: #d29922; color: #000; }
    .effort-high { background: #da3633; color: #fff; }

    .empty-placeholder {
      padding: 3rem; text-align: center; color: #6e7681;
      border: 1px dashed #30363d; border-radius: 6px;
    }

